import { parse } from 'yaml';
import { marked } from 'marked';

export interface Book {
	slug: string;
	title: string;
	author: string;
	year: number;
	rating: number;
	tags: string[];
	html: string;
}

const files = import.meta.glob('/content/books/*.md', {
	query: '?raw',
	import: 'default',
	eager: true
}) as Record<string, string>;

function load([path, raw]: [string, string]): Book {
	const slug = path.split('/').pop()!.replace(/\.md$/, '');
	const m = raw.replace(/\r\n/g, '\n').match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
	const data = m ? parse(m[1]) : {};
	return {
		slug,
		title: String(data.title),
		author: String(data.author),
		year: Number(data.year),
		rating: Number(data.rating),
		tags: (data.tags ?? []).map(String),
		html: marked.parse(m ? m[2] : raw, { async: false }) as string
	};
}

const byTitle = (a: Book, b: Book) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0);

export const books: Book[] = Object.entries(files).map(load).sort(byTitle);

export const getBook = (slug: string) => books.find((b) => b.slug === slug);

export const topRated = (n: number) =>
	[...books].sort((a, b) => b.rating - a.rating || byTitle(a, b)).slice(0, n);
EOF
